```C++
#include<iostream>
using namespace std;

int syn3a(int a, int &b){
    int c = 0;
    for(int i=a; i<=b; i+=2)
        c += i;
    a++;
    b++;
return c;
}
int main(){
    int x = 2, y = 7, z;
    z = syn3a(x,y);
    cout << x << endl;
    cout << y << endl;
    cout << z;
return 0;
